        {"call":"await Twinkle.mount.get()","returns":"{ type: 'subject', id: number } | null","summary":"Returns the host-provided mount context, such as a subject mounted into a book app.","notes":["Always available.","Does not fetch subject metadata, comments, or files. Use Twinkle.subjects and Twinkle.subjectComments for data reads."]},
        {"call":"await Twinkle.mount.refresh()","returns":"{ type: 'subject', id: number } | null","summary":"Forces a fresh mount context read from the parent frame.","notes":[]}
